-- WezTerm config. Theme values (scheme, font, palette) come from rice.lua, generated by chezmoi.
local wezterm = require 'wezterm'
local rice = require 'rice'
local c = rice.colors
local config = wezterm.config_builder()

-- ---- shell: WSL when it is installed, PowerShell otherwise ----
local wsl = wezterm.default_wsl_domains()
if #wsl > 0 then
  config.default_domain = wsl[1].name
else
  config.default_prog = { 'powershell.exe', '-NoLogo' }
end

-- ---- colors ----
local schemes = wezterm.color.get_builtin_schemes()
local scheme = schemes[rice.scheme]
if scheme then
  config.color_scheme = rice.scheme
else
  -- Theme without a matching built-in scheme: derive one from the rice palette
  scheme = {
    foreground = c.fg, background = c.bg,
    cursor_bg = c.accent, cursor_fg = c.crust, cursor_border = c.accent,
    selection_bg = c.surface2, selection_fg = c.fg,
    ansi = { c.surface, c.red, c.green, c.yellow, c.accent2, c.accent, c.accent2, c.fg },
    brights = { c.surface2, c.red, c.green, c.yellow, c.accent2, c.accent, c.accent2, c.fg },
  }
  config.color_schemes = { rice = scheme }
  config.color_scheme = 'rice'
end

-- Tab bar in the rice palette, so it matches Zebar / GlazeWM borders
config.colors = {
  tab_bar = {
    background = c.bg_dark,
    active_tab = { bg_color = c.accent, fg_color = c.crust, intensity = 'Bold' },
    inactive_tab = { bg_color = c.bg_dark, fg_color = c.muted },
    inactive_tab_hover = { bg_color = c.surface, fg_color = c.fg },
    new_tab = { bg_color = c.bg_dark, fg_color = c.muted },
    new_tab_hover = { bg_color = c.surface, fg_color = c.fg },
  },
}

-- ---- font (Japanese falls back to Windows' gothic fonts) ----
config.font = wezterm.font_with_fallback {
  rice.font,
  'BIZ UDGothic',
  'Yu Gothic',
}
config.font_size = rice.font_size
config.harfbuzz_features = { 'calt=1', 'liga=1' }

-- ---- window: no title bar (GlazeWM tiles it), tab bar only when needed ----
config.window_decorations = 'RESIZE'
config.window_padding = { left = 10, right = 10, top = 8, bottom = 8 }
config.use_fancy_tab_bar = false
config.tab_bar_at_bottom = true
config.hide_tab_bar_if_only_one_tab = true
config.tab_max_width = 32
config.adjust_window_size_when_changing_font_size = false
config.window_close_confirmation = 'NeverPrompt'
config.audible_bell = 'Disabled'

-- ---- input ----
config.use_ime = true
-- Alt+Enter belongs to GlazeWM (opens a terminal), not WezTerm's fullscreen toggle
config.keys = {
  { key = 'Enter', mods = 'ALT', action = wezterm.action.DisableDefaultAssignment },
}

return config
